import { init, wrapOpenAI, span, flush, shutdown } from 'neatlogs';
import OpenAI from 'openai';
await init({ apiKey: process.env.NEATLOGS_API_KEY, workflowName: 'veritas-smoke' });
const client = wrapOpenAI(new OpenAI({ baseURL: process.env.LITELLM_BASE_URL, apiKey: process.env.LITELLM_API_KEY }));
const lookup = span({ kind: 'TOOL', toolName: 'echo_tool' }, async (x) => `echo:${x}`);
const run = span({ kind: 'WORKFLOW' }, async () => {
  const t = await lookup('ping');
  const res = await client.chat.completions.create({
    model: process.env.VERITAS_MODEL_FAST, max_tokens: 20,
    messages: [{ role: 'user', content: 'Reply with the single word: ok' }],
  });
  return { t, text: res.choices[0].message.content, usage: res.usage, model: res.model };
});
try { console.log(JSON.stringify(await run())); } catch (e) { console.log('ERR', e?.status, e?.message); }
